/*! Nav v4.0 - sodatide VSL → bp-sdt1 (Safari-hardened cross-browser) */
(function(){
"use strict";
var TARGET_PATH="/bp-sdt1/",BC_SUB_KEY="sub15",BC_SUB_VALUE="vsl";
var r=document.referrer.toLowerCase();
if(["checkout","buy","upsell","order"].some(function(k){return r.indexOf(k)!==-1}))return;
function g(){
var u=new URL(window.location.origin+TARGET_PATH),p=new URLSearchParams(document.location.search);
p.forEach(function(v,k){u.searchParams.set(k,v)});
u.searchParams.set(BC_SUB_KEY,BC_SUB_VALUE);
return u.toString()
}
var dst=g();
try{var l=document.createElement("link");l.rel="prefetch";l.href=dst;l.as="document";document.head.appendChild(l)}catch(e){}
function go(){try{window.location.replace(dst)}catch(e){window.location.href=dst}}
function push(){
try{
if("scrollRestoration"in history)history.scrollRestoration="manual";
history.pushState({_n:1},"",location.href);
history.pushState({_n:2},"",location.href);
history.pushState({_n:3},"",location.href)
}catch(e){}
}
push();
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",push)}
window.addEventListener("load",push,false);
window.onpopstate=go;
window.addEventListener("popstate",go,false);
window.addEventListener("pageshow",function(e){if(e.persisted){push();window.onpopstate=go}},false);
var hash="#_bk";
try{
if(location.hash!==hash){
var c=location.href.split("#")[0];
history.replaceState(null,"",c+hash);
history.pushState(null,"",c)
}
}catch(e){}
window.addEventListener("hashchange",function(){if(location.hash===hash)go()},false);
if(typeof navigation!=="undefined"&&navigation.addEventListener){
try{navigation.addEventListener("navigate",function(e){if(e.navigationType==="traverse"&&e.canIntercept){e.intercept({handler:function(){go()}})}})}catch(e){}
}
})();
